import moment from 'moment';
// import * as XLSX from 'xlsx';
import * as XLSX from 'xlsx-js-style'; 


export function writeExcelFileSheets(
  sheetsData: {
    [sheetName: string]: {
      data: any[];
      headers?: string[];
      mapping?: { [key: string]: string };
    };
  },
  title: string
): void {
  // Tạo workbook mới
  const workbook: XLSX.WorkBook = { Sheets: {}, SheetNames: [] };

  // Duyệt qua mỗi sheet được định nghĩa trong sheetsData
  Object.keys(sheetsData).forEach(sheetName => {
    let { data, headers = [], mapping = {} } = sheetsData[sheetName];
    // Nếu có headers và mapping thì thực hiện chuyển đổi dữ liệu
    const finalData = headers.length > 0 && Object.keys(mapping).length > 0
      ? data.map((item: any) => {
          let newItem: { [key: string]: any } = {};
          headers.forEach((headerKey: string) => {
            // Tìm key tương ứng trong mapping
            const dataKey = Object.keys(mapping).find(key => mapping[key] === headerKey);
            const value = dataKey ? item[dataKey] : null;
            // Nếu giá trị là 0 thì giữ nguyên, ngược lại nếu falsy thì trả về null
            newItem[headerKey] = value === 0 ? 0 : (value || null);
          });
          return newItem;
        })
      : data;
    // Tạo worksheet từ finalData (hỗ trợ cả json và aoa)
    const worksheet: XLSX.WorkSheet = (finalData.length > 0 && Array.isArray(finalData[0]))
      ? XLSX.utils.aoa_to_sheet(finalData)
      : XLSX.utils.json_to_sheet(finalData);
      
    workbook.SheetNames.push(sheetName);
    workbook.Sheets[sheetName] = worksheet;
    applyBorders(worksheet);
  });
  if (workbook.SheetNames.length === 0) {
    workbook.SheetNames.push('EmptySheet');
    workbook.Sheets['EmptySheet'] = XLSX.utils.aoa_to_sheet([[]]);
  }

  const excelBuffer: any = XLSX.write(workbook, {
    bookType: 'xlsx',
    type: 'array',
    cellStyles: true,
  });

  saveAsExcelFile(excelBuffer, `${title}_${moment().format('DD_MM_YYYY')}`);
}





export function writeExcelFile(
  data: any,
  title: string,
  headers: string[] = [],
  mapping: { [key: string]: string } = {}
): void {

  const transfer = data.map((item: any) => {
    let newItem: { [key: string]: any } = {};
    headers.forEach((headerKey: string) => {
      // Tìm key tương ứng trong mapping
      const dataKey = Object.keys(mapping).find(key => mapping[key] === headerKey);
      newItem[headerKey] = dataKey ? item[dataKey] || null : null;
    });
    return newItem;
  });  
  const transformedData = headers.length > 0 && Object.keys(mapping).length > 0 ? transfer: data;
  const worksheet: XLSX.WorkSheet = XLSX.utils.json_to_sheet(transformedData);
  const workbook: XLSX.WorkBook = {
    Sheets: { Sheet1: worksheet },
    SheetNames: ['Sheet1'],
  };
  applyBorders(worksheet);

  const excelBuffer: any = XLSX.write(workbook, {
    bookType: 'xlsx',
    type: 'array',
    cellStyles: true,
  });
  saveAsExcelFile(excelBuffer, `${title}_${moment().format('DD_MM_YYYY')}`);
}

