function applyBorders(ws: XLSX.WorkSheet) {
  if (!ws['!ref']) return;
  const range = XLSX.utils.decode_range(ws['!ref']);
  for (let R = range.s.r; R <= range.e.r; ++R) {
    for (let C = range.s.c; C <= range.e.c; ++C) {
      const cell_address = { c: C, r: R };
      const cell_ref = XLSX.utils.encode_cell(cell_address);
      if (!ws[cell_ref]) ws[cell_ref] = { t: 'z', v: '' };
      if (!ws[cell_ref].s) ws[cell_ref].s = {};
      ws[cell_ref].s.border = {
        top: { style: 'thin', color: { rgb: '000000' } },
        bottom: { style: 'thin', color: { rgb: '000000' } },
        left: { style: 'thin', color: { rgb: '000000' } },
        right: { style: 'thin', color: { rgb: '000000' } }
      };
    }
  }
}

function saveAsExcelFile(buffer: any, fileName: string) {
  const data: Blob = new Blob([buffer], { type: 'application/octet-stream' });
  const url: string = window.URL.createObjectURL(data);
  const link: HTMLAnchorElement = document.createElement('a');
  link.href = url;
  link.download = `${fileName}.xlsx`;
  link.click();
  window.URL.revokeObjectURL(url);
  link.remove();
}

export function readExcelFile(event: any, sheetName?: any): Promise<any> {
  return new Promise((resolve, reject) => {
    // Chuẩn Angular CLI: import worker qua URL
    const worker = new Worker(
      new URL('./excel.worker', import.meta.url),
      { type: 'module' }
    );
    const file = event.target?.files?.[0] || event;
    worker.postMessage({ file, sheetName });
    worker.onmessage = (e: MessageEvent) => {
      if (e.data.result) {
        resolve(e.data.result);
      } else {
        reject(e.data.error);
      }
      worker.terminate();
    };
    worker.onerror = (err) => {
      reject(err);
      worker.terminate();
    };
  });
}


export function readExcelFileNoWorkerArray(event: any, sheetName?: string): Promise<any> {
  return new Promise((resolve, reject) => {
    const file = event.target?.files?.[0] || event;
    if (!file) {
      reject('No file provided');
      return;
    }
    const reader = new FileReader();
    reader.onload = (e: any) => {
      try {
      const data = new Uint8Array(e.target.result);
      const workbook = XLSX.read(data, { type: 'array' });
      let result: any;
      
      if (sheetName && workbook.SheetNames.includes(sheetName)) {
        result = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName], { defval: '' });
      } else {
        // Lấy sheet đầu tiên
        const firstSheetName = workbook.SheetNames[0];
        result = XLSX.utils.sheet_to_json(workbook.Sheets[firstSheetName], { defval: '' });
      }
      resolve(result);
      } catch (error) {
      reject(error);
      }
    };
    reader.onerror = (err) => reject(err);
    reader.readAsArrayBuffer(file);
  });
}

export function readExcelFileNoWorker(event: any, sheetName?: string): Promise<any> {
  return new Promise((resolve, reject) => {
    const file = event.target?.files?.[0] || event;
    if (!file) {
      reject('No file provided');
      return;
    }
    const reader = new FileReader();
    reader.onload = (e: any) => {
      try {
        const data = new Uint8Array(e.target.result);
        const workbook = XLSX.read(data, { type: 'array' });
        let result:any;
        if (sheetName && workbook.SheetNames.includes(sheetName)) {
          result = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName], { defval: '' });
        } else {
          result = {};
          workbook.SheetNames.forEach(name => {
            result[name] = XLSX.utils.sheet_to_json(workbook.Sheets[name], { defval: '' });
          });
        }
        resolve(result);
      } catch (error) {
        reject(error);
      }
    };
    reader.onerror = (err) => reject(err);
    reader.readAsArrayBuffer(file);
  });
}

export function excelSerialDateToJSDate(serial: any) {
  const excelEpochOffset = 25569;
  const millisecondsPerDay = 24 * 60 * 60 * 1000;
  const daysSinceUnixEpoch = serial - excelEpochOffset;
  const utcMilliseconds = daysSinceUnixEpoch * millisecondsPerDay;
  return new Date(utcMilliseconds);
}